//! Real owned motion fixtures generated by FFmpeg, no user capture/vendor media.
use std::process::Command;
pub fn motion(extension: &str) -> Vec<u8> {
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join(format!("motion.{extension}"));
    let mut command = Command::new("ffmpeg");
    command.args([
        "-nostdin",
        "-v",
        "error",
        "-f",
        "lavfi",
        "-i",
        "testsrc2=s=64x48:r=6",
        "-t",
        "1",
        "-threads",
        "1",
        "-filter_threads",
        "1",
    ]);
    if extension == "mp4" {
        command.args(["-c:v", "libx264", "-pix_fmt", "yuv420p"]);
    }
    let output = command.arg(&path).output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    std::fs::read(path).unwrap()
}
